                #[cfg(not(any(target_os = "android", target_os = "ios")))]
                MessageInput::BlockOffPlugin(_peer) => {
                    let (ok, _msg) = crate::platform::block_input(false);
                    if ok {
                        block_input_mode = false;
                    }
                    let _r = PLUGIN_BLOCK_INPUT_TX_RX
                        .0
                        .lock()
                        .unwrap()
